/** Card titles as published in Prismic, mapped to the live site's card ids. */
const TITLE_TO_LIVE_ID: Record<string, LiveId> = {
  "instant report": "instant-report",
  "ai-assistance": "ai-assistance",
  "land vs building allocation advisor": "land-building",
  "corrections on completed reports": "corrections",
  "catch up adjustment schedule - 481(a)": "catch-up",
  "audit support": "audit-support",
};

const normalize = (value: string) => value.toLowerCase().replace(/\s+/g, " ").trim();

/**
 * Resolves a Prismic card title to its live card id (also used as `data-id`).
 * Exact title match first, then keyword match so small copy edits in Prismic
 * don't drop the icon. Returns null for cards that have no live icon.
 */
export const liveIdFromTitle = (title: string | null | undefined): LiveId | null => {
  if (!title) return null;
  const key = normalize(title);
  if (key in TITLE_TO_LIVE_ID) return TITLE_TO_LIVE_ID[key];
  if (key.includes("instant")) return "instant-report";
  if (/\bai\b/.test(key)) return "ai-assistance";
  if (key.includes("land") && key.includes("building")) return "land-building";
  if (key.includes("correction")) return "corrections";
  if (key.includes("481") || key.includes("catch up") || key.includes("catch-up"))
    return "catch-up";
  if (key.includes("audit")) return "audit-support";
  return null;
};